import{_ as t,o as r,c as a,a0 as i}from"./chunks/framework.D4fUSYzX.js";const u=JSON.parse('{"title":"Prerequisites","description":"What the machine needs before the first start of the control plane.","frontmatter":{"title":"Prerequisites","description":"What the machine needs before the first start of the control plane."},"headers":[],"relativePath":"getting-started/prerequisites.md","filePath":"getting-started/prerequisites.md"}'),s={name:"getting-started/prerequisites.md"};function n(o,e,h,d,l,c){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h1><p>Before the first start, the machine needs:</p><ul><li>Node, for the <code>npx</code> that runs the installer. The installer downloads the prebuilt binary for your machine; the binary itself needs neither Node nor Bun.</li><li><a href="https://herdr.dev" target="_blank" rel="noreferrer">herdr</a> on the <code>PATH</code>, with a current <a href="https://ghostty.org" target="_blank" rel="noreferrer">ghostty</a> on the <code>PATH</code> (herdr runs each agent&#39;s terminal in ghostty), and <code>git</code>.</li><li>The agent CLI of each agent type you use, with its own provider auth applied.</li><li>Bun, only for the <a href="./first-launch.html#run-from-source">from-source path</a>.</li></ul><p>On macOS and Windows, the first run of a freshly downloaded binary shows the operating system&#39;s first-run warning, until you approve it.</p><p>On a musl Linux machine - Alpine and the Alpine-derived images - the binary needs the GNU C++ runtime, which the base image does not carry: install <code>libstdc++</code> (<code>apk add libstdc++</code>) before the first run.</p><p>Next: <a href="./first-launch.html">first launch</a>.</p>',6)])])}const f=t(s,[["render",n]]);export{u as __pageData,f as default};
